// Not cryptographic -- a stable content fingerprint used only to detect a
// stale or mismatched publish approval (see publication-policy.json).
function fnv1a32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const requestId = $('Review Trigger Webhook').first().json.body.request_id;
const manifest = ($json.contract.stage_artifacts && $json.contract.stage_artifacts.build_manifest) || [];
const sorted = [...manifest].sort((a, b) => String(a.artifact_key).localeCompare(String(b.artifact_key)));
const checksum = 'fnv1a32:' + fnv1a32(JSON.stringify(sorted));
return [{ json: { request_id: requestId, build_checksum: checksum, manifest: sorted, contract: $json.contract } }];

const ctx = $('Compute Build Checksum').first().json;
const requestId = ctx.request_id;
const manifest = ctx.manifest;
const contract = ctx.contract;
let livePosts = [];
try {
  const parsed = JSON.parse($json.result.content[0].text);
  livePosts = Array.isArray(parsed) ? parsed : (parsed.posts || []);
} catch (e) { livePosts = []; }

const placeholderPatterns = [/\{\{[^}]*\}\}/, /\bTODO\b/, /\bTBD\b/, /\[a completer\]/i, /\[a confirmer\]/i];
const findings = [];

const requiredPages = (contract.site && Array.isArray(contract.site.pages) && contract.site.pages.length) ? contract.site.pages : [];
const manifestKeys = new Set(manifest.map(m => m.artifact_key));
const missingPages = requiredPages.filter(p => !manifestKeys.has(p));
if (missingPages.length) {
  findings.push({ artifact_key: '', severity: 'critical', category: 'contract_conformance', evidence: 'Missing manifest entries for: ' + missingPages.join(', '), expected_correction: 'Build the missing pages before requesting review again.' });
}

const unverified = manifest.filter(m => m.verified !== true);
for (const m of unverified) {
  findings.push({ artifact_key: m.artifact_key, severity: 'critical', category: 'content', evidence: 'Manifest entry was not verified at build time (verified=' + m.verified + ')', expected_correction: 'Rebuild this artifact so the read-back verification passes.' });
}

for (const post of livePosts) {
  const text = (post.title || '') + ' ' + (post.content || post.excerpt || '');
  const hit = placeholderPatterns.find(p => p.test(text));
  if (hit) {
    findings.push({ artifact_key: post.slug || String(post.ID || post.id || ''), severity: 'critical', category: 'placeholder', evidence: 'Live content matches placeholder pattern ' + hit, expected_correction: 'Replace the placeholder with real content.' });
  }
}

return [{ json: { request_id: requestId, deterministic_findings: findings, deterministic_pass: findings.length === 0, manifest, contract, build_checksum: ctx.build_checksum, live_posts_count: livePosts.length } }];

const ctx = $json;
const prompt = `Tu es un reviewer WordPress independant, en lecture seule. Tu ne peux PAS modifier le site -- ton seul travail est d'evaluer.

Contrat: ${JSON.stringify(ctx.contract.business)} / ${JSON.stringify(ctx.contract.site)}
Manifest de build (ce qui a ete cree): ${JSON.stringify(ctx.manifest)}
Nombre de posts live detectes: ${ctx.live_posts_count}

Evalue qualitativement (tu n'as pas de navigateur, juge a partir du contenu fourni): coherence de navigation, presence de formulaires attendus, bases d'accessibilite, champs SEO, budget de performance raisonnable pour du contenu texte.

Reponds UNIQUEMENT avec un objet JSON de cette forme exacte, sans markdown, sans texte autour:
{"verdict": "approve", "findings": [{"artifact_key": "accueil", "severity": "minor", "category": "seo", "evidence": "...", "expected_correction": "..."}]}

verdict est "approve" seulement si tu n'as aucun finding de severite critical.`;
return [{ json: { request_id: ctx.request_id, prompt } }];

let parsed = null;
try { parsed = $json.parsed_json; } catch (e) { parsed = null; }
const agentVerdict = (parsed && parsed.verdict) || 'changes_requested';
const agentFindings = (parsed && Array.isArray(parsed.findings)) ? parsed.findings : [];
return [{ json: { agent_verdict: agentVerdict, agent_findings: agentFindings } }];

const det = $('Run Deterministic Checks').first().json;
const agent = $json;
const findings = [...det.deterministic_findings, ...agent.agent_findings];
const hasCritical = findings.some(f => f.severity === 'critical');
// Deterministic checks always win: a passing agent verdict cannot override a failed deterministic check.
const verdict = (det.deterministic_pass && agent.agent_verdict === 'approve' && !hasCritical) ? 'approve' : 'changes_requested';
return [{ json: { request_id: det.request_id, verdict, findings, build_checksum: det.build_checksum, deterministic_pass: det.deterministic_pass, agent_verdict: agent.agent_verdict } }];
